import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

/** A person of a crew: its lead or one of its members. */
export interface CrewPersonView {
  id: number;
  name: string;
}

/** A crew on the sheet: its lead (null once the lead has left the sheet) and its members, in the order added. */
export interface CrewView {
  id: number;
  name: string;
  lead: CrewPersonView | null;
  members: CrewPersonView[];
}

// The crews on the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class Crews {
  private readonly http = inject(HttpClient);
  private readonly list = signal<CrewView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's crews from the store; null clears them. */
  load(sheetId: string | null): Observable<CrewView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<CrewView[]>(this.base(sheetId)).pipe(tap((list) => this.list.set(list)));
  }

  /** Add a crew led by a person of the sheet; refused when the name is blank or already a crew on the sheet. */
  add(sheetId: string, name: string, leadId: number): Observable<CrewView> {
    return this.http.post<CrewView>(this.base(sheetId), { name, leadId }).pipe(
      tap((added) => this.list.update((list) => [...list, added])),
    );
  }

  /** Add a person to a crew; refused when they lead it or are already in it. */
  addMember(sheetId: string, crewId: number, personId: number): Observable<CrewView> {
    return this.http.post<CrewView>(`${this.base(sheetId)}/${crewId}/members`, { personId }).pipe(
      tap((saved) => this.list.update((list) => list.map((c) => (c.id === saved.id ? saved : c)))),
    );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/crews`;
  }
}
// each person's claims and due-total, and the sheet's claimed-total and due-total.
@Component({
  selector: 'app-people',
  imports: [ReactiveFormsModule, FigurePipe, SheetHeader, PersonClaims, PeriodsPanel, SummaryPanel, ClassicSummaryPanel, PoolsPanel, CrewsPanel, PersonPlans, PlanGenerate],
  template: `
    <app-header [peopleCount]="people().length" [statuses]="summaryByStatus()" [dueTotal]="dueTotal()"
                [overdueTotal]="money(overdueTotals().cents)" [myDueTotal]="me() ? dueOf(me()!) : ''"
                [myOverdueTotal]="me() ? money(overdueOf(me()!.id).cents) : ''" />
    <app-periods [dueTotals]="dueByPeriod()" />
    <app-pools [people]="people()" />
    <app-crews [people]="people()" [dueByPerson]="dueByPerson()" />
  protected sortBy(key: string): void {
    if (!(SORT_KEYS as readonly string[]).includes(key)) return;
    const user = this.session.user()?.trim().toLowerCase() ?? '';
    this.sortByUser.update((m) => new Map(m).set(user, key as SortKey));
  }

  protected dueOf(p: PersonView): string {
    const due = this.dueByPerson().get(p.id);
    return due === null || due === undefined ? NOT_AVAILABLE : money(due);
  }

  protected splitOf(personId: number): Split {
    return this.splitByPerson().get(personId) ?? NO_SPLIT;
  }

  /** How far the person's figures add up above the cap, in whole cents; 0 when they do not, or have no due-total. */
  protected excessOf(personId: number): number {
    const sum = this.uncappedDueByPerson().get(personId) ?? null;
    const due = this.dueByPerson().get(personId) ?? null;
    return sum === null || due === null ? 0 : sum - due;
  }

  /** Download the people as CSV, in list order, retired people included. */

